import React, { useState, useEffect } from 'react';
import confetti from 'canvas-confetti';
import { motion, AnimatePresence } from 'framer-motion';
import { FaCompactDisc, FaBullhorn, FaBolt, FaBackward, FaPalette } from 'react-icons/fa';

const DJPanel = ({ onSpeedChange, onFilterChange }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [audioContext, setAudioContext] = useState(null);

    useEffect(() => {
        setAudioContext(new (window.AudioContext || window.webkitAudioContext)());
    }, []);

    const playEffect = (type) => {
        if (!audioContext) return;
        if (audioContext.state === 'suspended') audioContext.resume();

        const osc = audioContext.createOscillator();
        const gainNode = audioContext.createGain();
        osc.connect(gainNode);
        gainNode.connect(audioContext.destination);

        const now = audioContext.currentTime;

        if (type === 'airhorn') {
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(400, now);
            osc.frequency.exponentialRampToValueAtTime(100, now + 0.5);
            gainNode.gain.setValueAtTime(0.5, now);
            gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.5);
            osc.start(now);
            osc.stop(now + 0.5);
        } else if (type === 'scratch') {
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(800, now);
            osc.frequency.linearRampToValueAtTime(100, now + 0.1);
            osc.frequency.linearRampToValueAtTime(800, now + 0.2);
            gainNode.gain.setValueAtTime(0.5, now);
            gainNode.gain.linearRampToValueAtTime(0.01, now + 0.2);
            osc.start(now);
            osc.stop(now + 0.2);
        } else if (type === 'laser') {
            osc.type = 'sine';
            osc.frequency.setValueAtTime(1000, now);
            osc.frequency.exponentialRampToValueAtTime(100, now + 0.3);
            gainNode.gain.setValueAtTime(0.3, now);
            gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
            osc.start(now);
            osc.stop(now + 0.3);
        } else if (type === 'rewind') {
            osc.type = 'square';
            osc.frequency.setValueAtTime(100, now);
            osc.frequency.exponentialRampToValueAtTime(1000, now + 0.5);
            gainNode.gain.setValueAtTime(0.3, now);
            gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.5);
            osc.start(now);
            osc.stop(now + 0.5);
        } else if (type === 'damnson') {
            // Simulated "Damn Son" (Choir-like chord)
            const osc2 = audioContext.createOscillator();
            osc.type = 'triangle';
            osc2.type = 'sine';
            osc.frequency.setValueAtTime(200, now); // Root
            osc2.frequency.setValueAtTime(300, now); // Fifth

            const gain2 = audioContext.createGain();
            osc2.connect(gain2);
            gain2.connect(audioContext.destination);

            gainNode.gain.setValueAtTime(0.5, now);
            gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.8);
            gain2.gain.setValueAtTime(0.3, now);
            gain2.gain.exponentialRampToValueAtTime(0.01, now + 0.8);

            osc.start(now);
            osc2.start(now);
            osc.stop(now + 0.8);
            osc2.stop(now + 0.8);
        }
    };

    const triggerConfetti = () => {
        confetti({
            particleCount: 100,
            spread: 70,
            origin: { y: 0.6 }
        });
    };

    const changeColor = (color) => {
        document.documentElement.style.setProperty('--primary-color', color);
        confetti({
            particleCount: 30,
            spread: 50,
            origin: { y: 0.8 },
            colors: [color]
        });
    };

    const togglePartyMode = () => {
        document.body.classList.toggle('party-mode');
        triggerConfetti();
    };

    return (
        <>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="fixed top-4 right-4 z-50 bg-red-600 text-white p-3 rounded-full shadow-lg hover:bg-red-700 transition transform hover:scale-110"
            >
                ≡ƒÄº DJ Panel
            </button>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ x: 300, opacity: 0 }}
                        animate={{ x: 0, opacity: 1 }}
                        exit={{ x: 300, opacity: 0 }}
                        className="fixed top-20 right-4 z-40 bg-gray-900 bg-opacity-90 backdrop-blur-xl p-6 rounded-2xl border border-gray-700 w-72 shadow-2xl overflow-y-auto max-h-[80vh]"
                    >
                        {/* ... (keep existing sections) ... */}

                        <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                            <FaCompactDisc className="animate-spin-slow" /> DJ Effects
                        </h3>

                        <div className="grid grid-cols-2 gap-3 mb-6">
                            <button onClick={() => playEffect('airhorn')} className="bg-gray-800 hover:bg-red-600 p-3 rounded-lg text-sm font-bold transition flex flex-col items-center gap-1 border border-gray-700">
                                <FaBullhorn /> Airhorn
                            </button>
                            <button onClick={() => playEffect('scratch')} className="bg-gray-800 hover:bg-blue-600 p-3 rounded-lg text-sm font-bold transition flex flex-col items-center gap-1 border border-gray-700">
                                <FaCompactDisc /> Scratch
                            </button>
                            <button onClick={() => playEffect('laser')} className="bg-gray-800 hover:bg-green-600 p-3 rounded-lg text-sm font-bold transition flex flex-col items-center gap-1 border border-gray-700">
                                <FaBolt /> Laser
                            </button>
                            <button onClick={() => playEffect('rewind')} className="bg-gray-800 hover:bg-yellow-600 p-3 rounded-lg text-sm font-bold transition flex flex-col items-center gap-1 border border-gray-700">
                                <FaBackward /> Rewind
                            </button>
                            <button onClick={() => playEffect('damnson')} className="bg-gray-800 hover:bg-purple-600 p-3 rounded-lg text-sm font-bold transition flex flex-col items-center gap-1 border border-gray-700 col-span-2">
                                ≡ƒÿ▓ Damn Son!
                            </button>
                        </div>

                        <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                            ≡ƒÄ¢∩╕Å Controls
                        </h3>
                        <div className="mb-6 space-y-4">
                            <div>
                                <label className="text-xs text-gray-400 mb-1 block">Playback Speed</label>
                                <input
                                    type="range" min="0.5" max="2" step="0.1" defaultValue="1"
                                    onChange={(e) => onSpeedChange && onSpeedChange(parseFloat(e.target.value))}
                                    className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                />
                            </div>
                            <div>
                                <label className="text-xs text-gray-400 mb-1 block">Low-Pass Filter</label>
                                <input
                                    type="range" min="0" max="20000" step="100" defaultValue="20000"
                                    onChange={(e) => onFilterChange && onFilterChange(parseFloat(e.target.value))}
                                    className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-green-500"
                                />
                            </div>
                        </div>

                        <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                            <FaPalette /> Lights
                        </h3>
                        <div className="flex justify-between mb-6">
                            {['#e63946', '#4cc9f0', '#f72585', '#4361ee', '#7209b7'].map(color => (
                                <button
                                    key={color}
                                    onClick={() => changeColor(color)}
                                    className="w-8 h-8 rounded-full border-2 border-white hover:scale-125 transition"
                                    style={{ backgroundColor: color }}
                                />
                            ))}
                        </div>

                        <button
                            onClick={togglePartyMode}
                            className="w-full bg-gradient-to-r from-purple-500 to-pink-500 py-3 rounded-xl font-bold text-white shadow-lg hover:opacity-90 transition transform hover:scale-105"
                        >
                            ≡ƒÄë Party Mode
                        </button>
                    </motion.div>
                )}
            </AnimatePresence>
        </>
    );
};

export default DJPanel;

import React, { useState, useEffect, useRef } from 'react';
import Deck from './Deck';
import Mixer from './Mixer';
import api from '../../api';
import { Link } from 'react-router-dom';

const DJStation = () => {
    const [songs, setSongs] = useState([]);
    const [audioContext, setAudioContext] = useState(null);

    // Audio Nodes Refs
    const nodesA = useRef({});
    const nodesB = useRef({});
    const masterGain = useRef(null);

    // State for Mixer UI
    const [crossfader, setCrossfader] = useState(0.5); // 0 = A, 1 = B
    const [eqA, setEqA] = useState({ high: 0, mid: 0, low: 0 });
    const [eqB, setEqB] = useState({ high: 0, mid: 0, low: 0 });

    useEffect(() => {
        const fetchSongs = async () => {
            try {
                const response = await api.get('songs/');
                setSongs(response.data);
            } catch (error) {
                console.error("Error fetching songs:", error);
            }
        };
        fetchSongs();

        // Init Audio Context
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        setAudioContext(ctx);

        // Create Master Output
        const master = ctx.createGain();
        master.connect(ctx.destination);
        masterGain.current = master;

        // Setup Channel A
        nodesA.current = createChannelStrip(ctx, master);

        // Setup Channel B
        nodesB.current = createChannelStrip(ctx, master);

        return () => {
            ctx.close();
        };
    }, []);

    const createChannelStrip = (ctx, destination) => {
        // Source (Input) -> EQ High -> EQ Mid -> EQ Low -> Gain (Fader) -> Destination
        const input = ctx.createGain(); // Placeholder input

        const high = ctx.createBiquadFilter();
        high.type = 'highshelf';
        high.frequency.value = 2500;

        const mid = ctx.createBiquadFilter();
        mid.type = 'peaking';
        mid.frequency.value = 1000;
        mid.Q.value = 1;

        const low = ctx.createBiquadFilter();
        low.type = 'lowshelf';
        low.frequency.value = 250;

        const gain = ctx.createGain();

        // Connect Chain
        input.connect(high);
        high.connect(mid);
        mid.connect(low);
        low.connect(gain);
        gain.connect(destination);

        return { input, high, mid, low, gain };
    };

    // Update Audio Params based on State
    useEffect(() => {
        if (!nodesA.current.gain || !nodesB.current.gain) return;

        // Crossfader Logic (Equal Power)
        // A: cos(x * PI / 2), B: sin(x * PI / 2) ? Or linear for simplicity
        // Linear: A = 1 - x, B = x
        const volA = Math.cos(crossfader * 0.5 * Math.PI);
        const volB = Math.cos((1 - crossfader) * 0.5 * Math.PI);

        nodesA.current.gain.gain.setTargetAtTime(volA, audioContext.currentTime, 0.1);
        nodesB.current.gain.gain.setTargetAtTime(volB, audioContext.currentTime, 0.1);

    }, [crossfader, audioContext]);

    useEffect(() => {
        if (!nodesA.current.high) return;
        nodesA.current.high.gain.value = eqA.high;
        nodesA.current.mid.gain.value = eqA.mid;
        nodesA.current.low.gain.value = eqA.low;
    }, [eqA]);

    useEffect(() => {
        if (!nodesB.current.high) return;
        nodesB.current.high.gain.value = eqB.high;
        nodesB.current.mid.gain.value = eqB.mid;
        nodesB.current.low.gain.value = eqB.low;
    }, [eqB]);

    return (
        <div className="min-h-screen flex flex-col items-center p-6 relative overflow-hidden">
            {/* Background Gradient */}
            <div className="absolute inset-0 bg-gradient-to-br from-[#0f0c29] via-[#302b63] to-[#24243e] -z-10"></div>

            <div className="w-full flex justify-between items-center mb-10 z-10">
                <Link to="/playlist" className="text-gray-300 hover:text-white flex items-center gap-2 transition hover:translate-x-[-5px]">
                    <span>ΓåÉ</span> Back to Playlist
                </Link>
                <h1 className="text-4xl font-black tracking-[0.2em] text-transparent bg-clip-text bg-gradient-to-r from-orange-400 via-pink-500 to-purple-500 drop-shadow-lg">
                    PRO DJ STATION
                </h1>
                <div className="w-24"></div>
            </div>

            <div className="flex flex-col md:flex-row gap-10 w-full max-w-[1400px] justify-center items-start z-10">
                {/* DECK A */}
                <div className="glass p-6 rounded-3xl shadow-2xl border border-white/10 relative group">
                    <div className="absolute -top-4 -left-4 bg-orange-500 text-white font-bold px-4 py-1 rounded-full shadow-lg">DECK A</div>
                    <Deck
                        id="A"
                        audioContext={audioContext}
                        outputNode={nodesA.current.input}
                        songs={songs}
                    />
                </div>

                {/* MIXER */}
                <div className="glass p-6 rounded-3xl shadow-2xl border border-white/10 flex flex-col items-center justify-center h-full">
                    <Mixer
                        crossfader={crossfader} setCrossfader={setCrossfader}
                        eqA={eqA} setEqA={setEqA}
                        eqB={eqB} setEqB={setEqB}
                    />
                </div>

                {/* DECK B */}
                <div className="glass p-6 rounded-3xl shadow-2xl border border-white/10 relative group">
                    <div className="absolute -top-4 -right-4 bg-purple-500 text-white font-bold px-4 py-1 rounded-full shadow-lg">DECK B</div>
                    <Deck
                        id="B"
                        audioContext={audioContext}
                        outputNode={nodesB.current.input}
                        songs={songs}
                    />
                </div>
            </div>
        </div>
    );
};

export default DJStation;

import React, { useState, useEffect, useRef } from 'react';
import { FaPlay, FaPause, FaStepBackward, FaRedo, FaSync } from 'react-icons/fa';

const Deck = ({ id, audioContext, outputNode, songs }) => {
    const [selectedSong, setSelectedSong] = useState(null);
    const [isPlaying, setIsPlaying] = useState(false);
    const [speed, setSpeed] = useState(1);
    const [loopIn, setLoopIn] = useState(null);
    const [loopOut, setLoopOut] = useState(null);
    const [isLooping, setIsLooping] = useState(false);

    const audioRef = useRef(new Audio());
    const sourceRef = useRef(null);

    useEffect(() => {
        if (selectedSong) {
            audioRef.current.src = selectedSong.song_file;
            audioRef.current.crossOrigin = "anonymous";
            audioRef.current.load();

            // Connect to Web Audio Graph
            if (audioContext && outputNode && !sourceRef.current) {
                try {
                    const src = audioContext.createMediaElementSource(audioRef.current);
                    sourceRef.current = src;
                    src.connect(outputNode);
                } catch (e) {
                    // console.log("Deck source connection error:", e);
                }
            }
        }
    }, [selectedSong, audioContext, outputNode]);

    useEffect(() => {
        audioRef.current.playbackRate = speed;
    }, [speed]);

    // Loop Logic
    useEffect(() => {
        const checkLoop = () => {
            if (isLooping && loopIn !== null && loopOut !== null) {
                if (audioRef.current.currentTime >= loopOut) {
                    audioRef.current.currentTime = loopIn;
                }
            }
        };
        audioRef.current.addEventListener('timeupdate', checkLoop);
        return () => audioRef.current.removeEventListener('timeupdate', checkLoop);
    }, [isLooping, loopIn, loopOut]);

    const togglePlay = () => {
        if (audioContext?.state === 'suspended') audioContext.resume();

        if (isPlaying) {
            audioRef.current.pause();
        } else {
            audioRef.current.play().catch(e => console.error(e));
        }
        setIsPlaying(!isPlaying);
    };

    const handleLoopIn = () => setLoopIn(audioRef.current.currentTime);
    const handleLoopOut = () => {
        setLoopOut(audioRef.current.currentTime);
        setIsLooping(true);
    };
    const clearLoop = () => {
        setIsLooping(false);
        setLoopIn(null);
        setLoopOut(null);
    };

    return (
        <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 w-full max-w-md shadow-2xl">
            <div className="flex justify-between items-center mb-4">
                <h2 className="text-2xl font-bold text-red-500">DECK {id}</h2>
                <select
                    className="bg-gray-700 text-white p-2 rounded text-sm max-w-[150px]"
                    onChange={(e) => setSelectedSong(songs.find(s => s.id === parseInt(e.target.value)))}
                >
                    <option value="">Select Track</option>
                    {songs.map(s => <option key={s.id} value={s.id}>{s.title}</option>)}
                </select>
            </div>

            {/* Vinyl / Cover Art */}
            <div className={`relative w-48 h-48 mx-auto mb-6 rounded-full border-4 border-gray-600 overflow-hidden shadow-lg ${isPlaying ? 'animate-spin-slow' : ''}`}>
                <img
                    src={selectedSong ? selectedSong.image : 'https://via.placeholder.com/150'}
                    alt="Cover"
                    className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-black opacity-20 rounded-full"></div>
                <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-12 h-12 bg-gray-900 rounded-full border-2 border-gray-500"></div>
            </div>

            {/* Controls */}
            <div className="flex justify-center gap-4 mb-4">
                <button onClick={togglePlay} className="bg-red-600 hover:bg-red-700 text-white p-4 rounded-full shadow-lg transition transform hover:scale-110">
                    {isPlaying ? <FaPause /> : <FaPlay />}
                </button>
                <button onClick={() => { audioRef.current.currentTime = 0; }} className="bg-gray-700 hover:bg-gray-600 text-white p-4 rounded-full transition">
                    <FaStepBackward />
                </button>
            </div>

            {/* Speed Slider */}
            <div className="mb-4">
                <label className="text-xs text-gray-400 flex justify-between">
                    <span>Speed</span>
                    <span>{Math.round(speed * 100)}%</span>
                </label>
                <input
                    type="range" min="0.5" max="1.5" step="0.01" value={speed}
                    onChange={(e) => setSpeed(parseFloat(e.target.value))}
                    className="w-full h-2 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-red-500"
                />
            </div>

            {/* Loop Controls */}
            <div className="flex justify-between gap-2">
                <button onClick={handleLoopIn} className={`flex-1 py-2 rounded font-bold text-xs ${loopIn !== null ? 'bg-yellow-600' : 'bg-gray-700'}`}>IN</button>
                <button onClick={handleLoopOut} className={`flex-1 py-2 rounded font-bold text-xs ${loopOut !== null ? 'bg-yellow-600' : 'bg-gray-700'}`}>OUT</button>
                <button onClick={clearLoop} className={`flex-1 py-2 rounded font-bold text-xs ${isLooping ? 'bg-green-600' : 'bg-gray-700'}`}>
                    {isLooping ? 'LOOPING' : 'EXIT'}
                </button>
            </div>
        </div>
    );
};

export default Deck;

