import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import { FaSearch, FaHeart, FaRegHeart } from 'react-icons/fa';
import api from '../../api';
import PlayerControls from './PlayerControls';
import DJPanel from './DJPanel';
import Visualizer from './Visualizer';

const SongCarousel = () => {
    const [allSongs, setAllSongs] = useState([]);
    const [songs, setSongs] = useState([]); // Filtered songs
    const [activeIndex, setActiveIndex] = useState(0);
    const [isPlaying, setIsPlaying] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [favorites, setFavorites] = useState([]);

    const audioRef = useRef(new Audio());

    // Web Audio API Refs
    const audioContextRef = useRef(null);
    const sourceRef = useRef(null);
    const filterRef = useRef(null);
    const analyserRef = useRef(null); // Analyser Ref

    useEffect(() => {
        // Load favorites from local storage
        const savedFavs = JSON.parse(localStorage.getItem('favorites') || '[]');
        setFavorites(savedFavs);

        // Initialize Web Audio API
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        const ctx = new AudioContext();
        audioContextRef.current = ctx;

        const filter = ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.value = 20000; // Default: Open
        filterRef.current = filter;

        const analyser = ctx.createAnalyser(); // Create Analyser
        analyser.fftSize = 256;
        analyserRef.current = analyser;
    }, []);

    useEffect(() => {
        api.get('songs/')
            .then(res => {
                setAllSongs(res.data);
                setSongs(res.data);
            })
            .catch(err => {
                console.error(err);
                if (err.response && (err.response.status === 401 || err.response.status === 403)) {
                    window.location.href = '/login';
                }
            });
    }, []);

    useEffect(() => {
        const results = allSongs.filter(song =>
            song.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
            song.artist.toLowerCase().includes(searchTerm.toLowerCase())
        );
        setSongs(results);
        setActiveIndex(0);
    }, [searchTerm, allSongs]);

    useEffect(() => {
        if (songs.length > 0) {
            const song = songs[activeIndex];
            if (audioRef.current.src !== song.song_file) {
                audioRef.current.src = song.song_file;
                if (isPlaying) {
                    audioRef.current.play().catch(e => console.error("Play error:", e));
                }
            }
        }
    }, [activeIndex, songs]);

    const togglePlay = () => {
        if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
            audioContextRef.current.resume();
        }
        setupAudioGraph();

        if (isPlaying) {
            audioRef.current.pause();
        } else {
            audioRef.current.play().catch(e => console.error("Play error:", e));
        }
        setIsPlaying(!isPlaying);
    };

    const handleNext = () => {
        setActiveIndex((prev) => (prev + 1) % songs.length);
    };

    const handlePrev = () => {
        setActiveIndex((prev) => (prev - 1 + songs.length) % songs.length);
    };

    const handleSpeedChange = (speed) => {
        if (audioRef.current) {
            audioRef.current.playbackRate = speed;
        }
    };

    const handleFilterChange = (freq) => {
        if (filterRef.current) {
            filterRef.current.frequency.value = freq;
        }
    };

    const toggleFavorite = (id) => {
        let newFavs;
        if (favorites.includes(id)) {
            newFavs = favorites.filter(fav => fav !== id);
        } else {
            newFavs = [...favorites, id];
        }
        setFavorites(newFavs);
        localStorage.setItem('favorites', JSON.stringify(newFavs));
    };

    const handleDelete = async (id) => {
        if (window.confirm('Are you sure you want to delete this song?')) {
            try {
                await api.delete(`songs/${id}/`);
                const newSongs = allSongs.filter(song => song.id !== id);
                setAllSongs(newSongs);
                if (activeIndex >= newSongs.length) setActiveIndex(0);
            } catch (err) {
                console.error("Delete failed:", err);
            }
        }
    };

    return (
        <div className="flex flex-col items-center justify-center min-h-screen overflow-hidden relative">
            <DJPanel onSpeedChange={handleSpeedChange} onFilterChange={handleFilterChange} />

            {/* ... (keep existing links and search) ... */}
            <Link to="/dj" className="absolute top-6 left-6 z-50 bg-gradient-to-r from-orange-500 to-pink-500 text-white px-6 py-3 rounded-full font-bold shadow-lg hover:shadow-pink-500/50 transition transform hover:scale-105 flex items-center gap-2">
                <span>≡ƒÄ¢∩╕Å</span> Pro DJ Mode
            </Link>

            <Link to="/add-song" className="absolute top-6 right-6 z-50 bg-white/10 backdrop-blur-md text-white px-6 py-3 rounded-full font-bold border border-white/20 hover:bg-white/20 transition transform hover:scale-105 flex items-center gap-2">
                <span>Γ₧ò</span> Add Song
            </Link>

            {/* Search Bar */}
            <div className="absolute top-6 left-1/2 transform -translate-x-1/2 z-50 w-80">
                <div className="relative group">
                    <FaSearch className="absolute left-4 top-3.5 text-gray-300 group-focus-within:text-pink-500 transition" />
                    <input
                        type="text"
                        placeholder="Search songs..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full glass text-white pl-12 pr-4 py-3 rounded-full border border-white/10 focus:border-pink-500 focus:ring-2 focus:ring-pink-500/50 focus:outline-none transition placeholder-gray-400"
                    />
                </div>
            </div>

            {/* Background Blur */}
            <div
                className="absolute inset-0 bg-cover bg-center blur-3xl opacity-40 transition-all duration-1000 scale-110"
                style={{ backgroundImage: `url(${songs[activeIndex]?.image || ''})` }}
            />

            <div className="relative z-10 w-full max-w-5xl h-[600px] flex items-center justify-center perspective-1000">
                <AnimatePresence mode='popLayout'>
                    {songs.length === 0 ? (
                        <div className="text-white text-2xl glass p-8 rounded-xl">No songs found</div>
                    ) : (
                        songs.map((song, index) => {
                            // Logic to show only 3 cards: prev, active, next
                            let position = 0; // 0 = center, -1 = left, 1 = right, 2 = hidden

                            if (index === activeIndex) position = 0;
                            else if (index === (activeIndex - 1 + songs.length) % songs.length) position = -1;
                            else if (index === (activeIndex + 1) % songs.length) position = 1;
                            else position = 2;

                            if (position === 2) return null;

                            const isFav = favorites.includes(song.id);

                            return (
                                <motion.div
                                    key={song.id}
                                    layout
                                    initial={{ scale: 0.8, opacity: 0 }}
                                    animate={{
                                        x: position * 320,
                                        scale: position === 0 ? 1.1 : 0.8,
                                        opacity: position === 0 ? 1 : 0.4,
                                        zIndex: position === 0 ? 10 : 5,
                                        rotateY: position * -25
                                    }}
                                    exit={{ scale: 0.8, opacity: 0 }}
                                    transition={{ type: "spring", stiffness: 200, damping: 25 }}
                                    className={`absolute w-80 h-[450px] glass rounded-3xl shadow-2xl overflow-hidden cursor-pointer group border border-white/10 ${position === 0 ? 'ring-2 ring-[var(--primary-color)]' : ''}`}
                                    onClick={() => {
                                        if (position !== 0) setActiveIndex(index);
                                    }}
                                >
                                    <div className="relative h-72 overflow-hidden">
                                        <img src={song.image} alt={song.title} className="w-full h-full object-cover transition duration-700 group-hover:scale-110" />
                                        <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent"></div>
                                    </div>

                                    <div className="p-6 text-center relative -mt-12">
                                        <h3 className="text-2xl font-bold text-white truncate drop-shadow-lg">{song.title}</h3>
                                        <p className="text-gray-300 text-sm mt-1">{song.artist}</p>

                                        <div className="absolute top-[-260px] right-4 flex flex-col gap-3">
                                            <button
                                                onClick={(e) => { e.stopPropagation(); toggleFavorite(song.id); }}
                                                className="text-white p-3 glass rounded-full hover:bg-white/20 transition transform hover:scale-110"
                                            >
                                                {isFav ? <FaHeart className="text-red-500 text-xl" /> : <FaRegHeart className="text-xl" />}
                                            </button>
                                            <Link
                                                to={`/edit-song/${song.id}`}
                                                onClick={(e) => e.stopPropagation()}
                                                className="text-white p-3 glass rounded-full hover:bg-white/20 transition transform hover:scale-110 flex items-center justify-center"
                                            >
                                                Γ£Å∩╕Å
                                            </Link>
                                            <button
                                                onClick={(e) => { e.stopPropagation(); handleDelete(song.id); }}
                                                className="text-white p-3 glass rounded-full hover:bg-red-500/50 transition transform hover:scale-110 flex items-center justify-center"
                                            >
                                                ≡ƒùæ∩╕Å
                                            </button>
                                        </div>
                                    </div>
                                </motion.div>
                            );
                        })
                    )}
                </AnimatePresence>
            </div>

            <PlayerControls
                isPlaying={isPlaying}
                onPlayPause={togglePlay}
                onNext={handleNext}
                onPrev={handlePrev}
                audioRef={audioRef}
            />

            {/* Visualizer */}
            <Visualizer analyser={analyserRef.current} />
        </div>
    );
};

export default SongCarousel;
